## chamadas
- bash (intenção: Adding table selection TS type | comando: cd /home/one/projects/one/rich-editor-auy && python3 - <<'EOF'
p='packages/ts/packages/core/mod.ts'
s=open(p).read()
s=s.replace("""/** Serialized selection. */
export type SelectionJSON =
  | { readonly type: "none" }
  | { readonly type: "caret"; readonly pos: number; readonly assoc?: -1 | 1 }
  | {
    readonly type: "text";
    readonly anchor: number;
    readonly head: number;
    readonly assoc?: -1 | 1;
  }
  | { readonly type: "node"; readonly pos: number };""",
"""/** Serialized table cell reference. */
export interface CellRefJSON {
  readonly table: number;
  readonly row: number;
  readonly column: number;
}

/** Serialized selection. */
export type SelectionJSON =
  | { readonly type: "none" }
  | { readonly type: "caret"; readonly pos: number; readonly assoc?: -1 | 1 }
  | {
    readonly type: "text";
    readonly anchor: number;
    readonly head: number;
    readonly assoc?: -1 | 1;
  }
  | { readonly type: "node"; readonly pos: number }
  | {
    readonly type: "table";
    readonly table: number;
    readonly anchor: CellRefJSON;
    readonly head: CellRefJSON;
  };""")
open(p,'w').write(s)
print("ok")
EOF)

